mapper.select:
select LL.LOINC_CD loincCode,CLT.DESCRIPTION loincDescription,
CLT.TEST_TYPE testType, CLT.UNIT_OF_RESULT unitOfResult from
CODED_LAB_TEST_TYPE CLT, LAB_LOINC LL where CLT.TEST_TYPE_CD =
LL.TEST_TYPE_CD

	and LL.LOINC_CD like #{loincCode}


	AND CLT.DESCRIPTION LIKE #{loincDescription}


	AND CLT.TEST_TYPE = #{testType}


	AND CLT.UNIT_OF_RESULT = #{unitOfResult}


	AND CLT.UNIT_OF_RESULT is null

select ATR_DOMAIN_CD from ACCPTD_TST_RESULT_DOMAIN where
(VALUE_TYPE || '|' || STRING_VALUE || '|' || RANGE_LOWER_BOUND || '|'
|| RANGE_UPPER_BOUND) = #{inputData}

select count(*) from LOINC_ACCPTD_TST_RESULT_DOMAIN where FLAG_ACTIVE
= 'Y' and LOINC_CD = #{loincCode} and ATR_DOMAIN_CD in

	#{atrDomainId}

mapper.update:
UPDATE LOINC_ACCPTD_TST_RESULT_DOMAIN set FLAG_ACTIVE = #{flagActive},
LAST_UPDATED_BY = #{p_lastUpdatedBy}, LAST_UPDATED_DATE = SYSDATE
where LATRD_ID = #{loincAtrDomainMapId}

mapper.select:
		select DISTINCT NVL(UNIT_OF_RESULT,'') UNIT_OF_RESULT from CODED_LAB_TEST_TYPE
		
			where DESCRIPTION = #{loincDescription} and TEST_TYPE = #{testType}
		
		 order by UNIT_OF_RESULT

select TEST_TYPE_CD from CODED_LAB_TEST_TYPE where DESCRIPTION = #{loincDescription} and TEST_TYPE = #{testType} and
UNIT_OF_RESULT is null
UNIT_OF_RESULT = #{unitOfResult}

 
	
		select count(*) from raw_hiv_eclrs_Doc where (MSHLABPFI not in ('3263') or obxloinccode not in ('81641-3'))    
		
		 and document_id in
		
			#{documentId}
